{
  "packet_id": "H6-T01-1",
  "claim_id": "C063",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C063.component",
    "value": "Evaluation should check that apparent improvement does not consist merely of shifting starts later.",
    "scope": "An interpretation limit on apparent improvement, not an assertion that starts have shifted. Whether starts means scheduled or actual starts is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P029 explicitly requires checking whether apparent improvement merely shifts starts later."
    }
  },
  "signal_basis": {
    "component_id": "C063.signal_basis",
    "value": "Continued comparable trial measurements show sustained apparent improvement across repeated periods, assessed using late-booking rates, delay minutes and stage-specific counts, with consistent definitions of scheduled and actual starts.",
    "scope": "Assumed improvement during the predefined trial period; the pattern alone does not establish whether starts have shifted later.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply consistent event definitions, evaluation measures, continued trial observations and the sustained-improvement signal."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C063.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this interpretation check."
    }
  },
  "rationale": "Repeated improvement in recorded delays warrants checking whether the apparent benefit reflects later starts rather than improved turnaround. Persistence alone cannot exclude that possibility. The claim requires a check and does not infer that shifting occurred.",
  "uncertainty": "The mapping leaves scheduled versus actual starts unspecified. This limits the check's operational precision but does not undermine its warrant as an interpretation limit.",
  "anomalies": []
}
